INSERT INTO `email_templates` (`id`, `name`, `subject`, `body`, `category`) VALUES
(1, 'Leave of absence', 'prayer for leave of absence ', '   Dear Sir,\n\n   I hope you are well. I could not attend the class today due to unavoidable reason/sickness/heavy rain road block.\n\n   Course: {{course}}\n   Section: {{section}}\n   ID: {{id}}\n   Name: {{name}}', NULL),
(2, 'Add courses', 'For adding courses for the upcoming trimester', 'Dear Sir,<br>\nI hope that you are doing well. I am willing to Add the courses mentioned below.<br><br>\nCourses: {{courses}}\n<br>\nName: {{name}}<br>\nID: {{id}}<br><br>\nThank you,', NULL),
(3, 'Drop courses', 'For dropping some courses for the upcoming trimester', 'Dear Sir,<br>\nI hope that you are doing well. I am willing to drop the courses mentioned below.<br><br>\nCourses: {{courses}}\n<br>\nName: {{name}}<br>\nID: {{id}}<br><br>\nThank you,', NULL);
